\label{form:original}
The partitionwise convex quadratic model is used directly as
\begin{equation}
f_{k,r}^{\mathrm{lb}}(z)
=
m_{k,r}(z),
\qquad
z=(s_k,x_k).
\label{eq:lb_formulation_one}
\end{equation}

\label{form:corrected}

Define the local block-partition domain as
\begin{equation}
Z_{k,r}^{(q)}
=
S_k^{(q)}
\times
X_{k,r}.
\label{eq:local_block_partition_domain}
\end{equation}
The fill distance of the fitting set over this domain is
\begin{equation}
h_{k,r}^{(q)}
=
\sup_{z\in Z_{k,r}^{(q)}}
\min_{z^i\in\mathcal Z_{k,r}^{\mathrm{fit}}}
\|z-z^i\|.
\label{eq:local_fill_distance}
\end{equation}
Define the residual as
\begin{equation}
e_{k,r}(z)
=
f_k(z)-m_{k,r}(z).
\label{eq:residual_definition}
\end{equation}
The corrected lower-bounding model is
\begin{equation}
f_{k,r}^{\mathrm{lb}}(z)
=
m_{k,r}(z)
-
B_{k,r}h_{k,r}^{(q)},
\qquad
z\in Z_{k,r}^{(q)},
\label{eq:lb_formulation_two}
\end{equation}
where
\begin{equation}
B_{k,r}
=
\rho_{k,r}B_{k,r}^{\mathrm{raw}}
+
\omega_{k,r},
\qquad
\rho_{k,r}\geq 1,
\qquad
\omega_{k,r}>0,
\label{eq:residual_safety_factor}
\end{equation}
$\rho_{k,r}\geq 1$ is a residual-slope safety factor,
$\omega_{k,r}>0$ is an additive residual safety margin, and
$B_{k,r}^{\mathrm{raw}}$ is the raw sampled residual slope defined later.

\label{assump:local_smoothness}
For each node $q$, block $k$, and partition $r$, the block function $f_k$
belongs to $C^{1,1}(Z_{k,r}^{(q)})$, i.e., $f_k$ is continuously
differentiable with Lipschitz-continuous gradient on $Z_{k,r}^{(q)}$.
There exists a constant $L_{k,r}^{(q)}>0$ such that
\begin{equation}
\|\nabla f_k(z)-\nabla f_k(y)\|
\le
L_{k,r}^{(q)}
\|z-y\|,
\qquad
z,y\in Z_{k,r}^{(q)}.
\label{eq:block_gradient_lipschitz}
\end{equation}

\label{lem:sampled_residual_bound}
Suppose Assumption~\ref{assump:local_smoothness} holds and the selected
neighbor directions span the local joint space. Then, for every
$z^i\in\mathcal Z^{\mathrm{fit}}$,
\begin{equation}
\|\nabla e(z^i)\|
\le
\kappa
\left(
B^{\mathrm{raw}}
+
\frac{H}{2}d_{\mathcal N}
\right).
\label{eq:sample_gradient_bound}
\end{equation}
Furthermore, using the fill distance $h$ and the nonnegative fitting
residuals in \eqref{eq:nonnegative_fitting_residual}, for every $z\in Z$,
\begin{equation}
e(z)
\ge
-
\left[
\kappa B^{\mathrm{raw}}
+
\frac{H}{2}
\left(
\kappa d_{\mathcal N}+h
\right)
\right]h.
\label{eq:global_residual_bound}
\end{equation}

\label{prop:formulation_two_deterministic}
Under the conditions of Lemma~\ref{lem:sampled_residual_bound},
the corrected model in Formulation~\ref{form:corrected} is a valid lower
bound on $Z$ whenever
\begin{equation}
\rho B^{\mathrm{raw}}+\omega
\ge
\kappa B^{\mathrm{raw}}
+
\frac{H}{2}
\left(
\kappa d_{\mathcal N}+h
\right),
\label{eq:deterministic_formulation_two_condition}
\end{equation}
or equivalently,
\begin{equation}
(\rho-\kappa)B^{\mathrm{raw}}+\omega
\ge
\frac{H}{2}
\left(
\kappa d_{\mathcal N}+h
\right).
\label{eq:deterministic_formulation_two_condition_equivalent}
\end{equation}
Whenever this condition holds,
\begin{equation}
f^{\mathrm{lb}}(z)
\le
f(z),
\qquad
z\in Z.
\label{eq:deterministic_formulation_two_validity}
\end{equation}

\label{thm:probabilistic_formulation_two}
Suppose Assumption~\ref{assump:local_smoothness} holds. Let the $N_s$ newly
generated coupling samples be drawn independently and uniformly from the
current coupling region and included in the fitting set. Suppose further that
\begin{equation}
\rho\geq\Gamma_0,
\qquad
\omega>0,
\qquad
h_\omega>h_X.
\end{equation}
Then
\begin{equation}
\Pr
\left(
\mathcal G
\cap
\left\{
\exists z\in Z:
f^{\mathrm{lb}}(z)>f(z)
\right\}
\right)
\leq
\delta(\omega,N_s),
\label{eq:probabilistic_formulation_two_failure}
\end{equation}
where
\begin{equation}
\delta(\omega,N_s)
=
\min
\left\{
1,\,
J_\omega^{d_{s_k}}
\left(
1-\frac{1}{J_\omega^{d_{s_k}}}
\right)^{N_s}
\right\}.
\label{eq:formulation_two_failure_probability}
\end{equation}
Thus, the probability that the geometric acceptance condition is satisfied
and the corrected lower bound is nevertheless invalid is at most
$\delta(\omega,N_s)$. Consequently, when lower bounds are used only after
the geometric acceptance condition is satisfied, the probability of an
accepted-but-invalid lower bound is bounded above by
$\delta(\omega,N_s)$.

\label{prop:reduced_lb_validity}
Suppose that, for every block $k$ and private partition $r$ at node $q$,
the corrected model satisfies
\begin{equation}
f^{\mathrm{lb}}_{k,r}(z)
\leq
f_k(z),
\qquad
z\in Z_{k,r}^{(q)}.
\label{eq:block_lb}
\end{equation}
Then
\begin{equation}
\mathrm{LB}^{(q)}
=
\min_{s\in S^{(q)}}
\sum_{k=1}^{K}
\min_{r=1,\ldots,R_k}
g_{k,r}(s_k)
\label{eq:node_lb_valid}
\end{equation}
is a valid lower bound on the objective over node $q$.

Fix $s\in S^{(q)}$. For every block $k$ and partition $r$,
minimizing \eqref{eq:block_lb} over $x_k\in X_{k,r}$ gives
\begin{equation}
g_{k,r}(s_k)
\leq
\min_{x_k\in X_{k,r}}
f_k(s_k,x_k).
\end{equation}
Taking the minimum over all private partitions and using
$X_k=\bigcup_{r=1}^{R_k}X_{k,r}$ yields
\begin{equation}
\min_{r=1,\ldots,R_k}
g_{k,r}(s_k)
\leq
\min_{x_k\in X_k}
f_k(s_k,x_k).
\end{equation}
Since the private variables are independent across blocks for fixed $s$,
\begin{equation}
\sum_{k=1}^{K}
\min_{r=1,\ldots,R_k}
g_{k,r}(s_k)
\leq
\min_{x_1\in X_1,\ldots,x_K\in X_K}
\sum_{k=1}^{K}
f_k(s_k,x_k).
\end{equation}
Minimizing both sides over $s\in S^{(q)}$ establishes the result.

\label{assump:exhaustive_branching}
Along any infinite nested sequence of active outer nodes, the branching rule
satisfies
\begin{equation}
\operatorname{diam}\!\left(S^{(q)}\right)
\rightarrow 0.
\label{eq:coupling_diameter_decay}
\end{equation}

\label{prop:local_domain_refinement}
Under the private-partition refinement rule for $M_\nu$ in
Algorithm~\ref{alg:two_level_ddbb}, along any infinite sequence of outer
nodes with levels $\nu\rightarrow\infty$,
\begin{equation}
\max_{k,r}
\operatorname{diam}\!\left(X_{k,r}^{(\nu)}\right)
\rightarrow 0.
\label{eq:private_diameter_decay}
\end{equation}
Consequently, under Assumption~\ref{assump:exhaustive_branching},
\begin{equation}
\max_{k,r}
\operatorname{diam}\!\left(Z_{k,r}^{(q)}\right)
\rightarrow 0.
\label{eq:local_domain_diameter_decay}
\end{equation}

Since $\gamma>1$, the prescribed refinement schedule satisfies
\begin{equation}
M_\nu\rightarrow\infty
\qquad\text{as}\qquad
\nu\rightarrow\infty.
\end{equation}
Uniform partitioning of each private-variable component therefore implies
\eqref{eq:private_diameter_decay}. Moreover,
\begin{equation}
Z_{k,r}^{(q)}
=
S_k^{(q)}
\times
X_{k,r}^{(\nu)}.
\end{equation}
Assumption~\ref{assump:exhaustive_branching} gives
$\operatorname{diam}(S_k^{(q)})\rightarrow0$, while
\eqref{eq:private_diameter_decay} gives
$\operatorname{diam}(X_{k,r}^{(\nu)})\rightarrow0$.
Hence, \eqref{eq:local_domain_diameter_decay} follows.

\label{assump:lb_consistency}
Along any infinite sequence of refined nodes,
\begin{equation}
\max_{k,r}
\sup_{z\in Z_{k,r}^{(q)}}
\left[
f_k(z)
-
f^{\mathrm{lb}}_{k,r}(z)
\right]
\rightarrow 0.
\label{eq:lb_consistency}
\end{equation}

\label{thm:convergence}
Suppose Assumptions~\ref{assump:exhaustive_branching},
\ref{assump:exhaustive_node_refinement}, and
\ref{assump:lb_consistency} hold. Suppose further that every accepted
partitionwise corrected model satisfies the deterministic validity condition
of Proposition~\ref{prop:formulation_two_deterministic}. Then the
residual-corrected two-level branch-and-bound algorithm is globally
convergent. In particular, if the algorithm terminates with
\begin{equation}
\mathrm{UB}^{\star}
-
\mathrm{LB}^{\star}
\leq
\epsilon,
\label{eq:global_termination}
\end{equation}
where $\mathrm{LB}^{\star}$ denotes the global lower bound over the active
nodes, then the incumbent solution $x^\star$ satisfies
\begin{equation}
f(x^\star)-f^\star
\leq
\epsilon,
\label{eq:epsilon_global_optimality}
\end{equation}
where $f^\star$ denotes the global optimal objective value.

Under the geometric acceptance condition $\mathcal G$,
$\kappa\leq\Gamma_0$ and $d_{\mathcal N}\leq\Gamma_0 h$.
Since $\rho\geq\Gamma_0$, it follows that $\rho-\kappa\geq0$.
Because $B^{\mathrm{raw}}\geq0$,
\begin{equation}
(\rho-\kappa)B^{\mathrm{raw}}
\geq0.
\label{eq:app_nonnegative_residual_margin}
\end{equation}

By the geometric bounds,
\begin{equation}
\frac{H}{2}
\left(
\kappa d_{\mathcal N}+h
\right)
\leq
\frac{H}{2}
\left(
\Gamma_0^2+1
\right)h.
\label{eq:app_geometric_smoothness_bound}
\end{equation}

If $h\leq h_\omega=2\omega/[H(\Gamma_0^2+1)]$, then
\begin{equation}
\frac{H}{2}
\left(
\Gamma_0^2+1
\right)h
\leq
\omega.
\label{eq:app_omega_dominates_smoothness}
\end{equation}
Combining
\eqref{eq:app_nonnegative_residual_margin},
\eqref{eq:app_geometric_smoothness_bound}, and
\eqref{eq:app_omega_dominates_smoothness} gives
\begin{equation}
(\rho-\kappa)B^{\mathrm{raw}}
+
\omega
\geq
\frac{H}{2}
\left(
\kappa d_{\mathcal N}+h
\right).
\end{equation}
Thus, the deterministic validity condition
\eqref{eq:deterministic_formulation_two_condition_equivalent}
holds. Therefore, by
Proposition~\ref{prop:formulation_two_deterministic},
the corrected model is a valid lower bound on $Z$.
